begin;
create schema ntf;
set local search_path=ntf,public;
create table ntf_products(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null);
create table ntf_organizations(id uuid primary key default gen_random_uuid(), name text not null);
create table ntf_tenants(id uuid primary key default gen_random_uuid(), product_id uuid not null references ntf_products, organization_id uuid not null references ntf_organizations, active boolean not null default true, unique(product_id,organization_id), unique(id,product_id));
create table ntf_users(tenant_id uuid references ntf_tenants, user_id text, display_name text, email text, phone text, active boolean not null default true, primary key(tenant_id,user_id));
create table ntf_roles(tenant_id uuid references ntf_tenants, code text, name text not null, primary key(tenant_id,code));
create table ntf_user_roles(tenant_id uuid, user_id text, role_code text, primary key(tenant_id,user_id,role_code), foreign key(tenant_id,user_id) references ntf_users, foreign key(tenant_id,role_code) references ntf_roles);
create table ntf_events(product_id uuid references ntf_products, code text, version integer check(version>0), module_code text not null, trigger_type text not null check(trigger_type in ('WORKFLOW_TRANSITION','STATUS_CHANGE','ACTION','RECORD_CREATED','RECORD_UPDATED','ASSIGNMENT','SCHEDULED','MANUAL','SYSTEM_EVENT')), metadata jsonb not null default '{}', payload_schema jsonb not null, primary key(product_id,code,version));
create table ntf_templates(id uuid primary key default gen_random_uuid(), code text unique not null);
create table ntf_template_versions(template_id uuid references ntf_templates, version integer check(version>0), channel text check(channel in ('IN_APP','PUSH','SMS','WHATSAPP')), locale text, content jsonb not null, variables jsonb not null default '{}', status text not null check(status in ('DRAFT','PUBLISHED','RETIRED')), primary key(template_id,version,channel,locale));
create table ntf_overrides(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references ntf_tenants, template_id uuid not null, base_version integer not null, channel text not null, locale text not null, version integer not null check(version>0), patch jsonb not null, status text not null check(status in ('DRAFT','PUBLISHED','RETIRED')), foreign key(template_id,base_version,channel,locale) references ntf_template_versions, unique(tenant_id,template_id,channel,locale,version));
create unique index ntf_override_published on ntf_overrides(tenant_id,template_id,channel,locale) where status='PUBLISHED';
create table ntf_channels(tenant_id uuid references ntf_tenants, channel text check(channel in ('IN_APP','PUSH','SMS','WHATSAPP')), enabled boolean not null default false, provider_config jsonb not null default '{}', primary key(tenant_id,channel));
create table ntf_rules(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, product_id uuid not null, event_code text not null, event_version integer not null, version integer not null default 1, active boolean not null default false, conditions jsonb not null default '{}', recipient_strategy text not null, role_code text, priority integer not null default 0, purpose text not null, schedule_config jsonb not null default '{}', foreign key(tenant_id,product_id) references ntf_tenants(id,product_id), foreign key(product_id,event_code,event_version) references ntf_events, foreign key(tenant_id,role_code) references ntf_roles, unique(id,tenant_id));
create table ntf_rule_channels(rule_id uuid, tenant_id uuid, channel text, template_id uuid not null, template_version integer not null, locale text not null default 'en', mappings jsonb not null default '{}', primary key(rule_id,channel), foreign key(rule_id,tenant_id) references ntf_rules(id,tenant_id), foreign key(tenant_id,channel) references ntf_channels, foreign key(template_id,template_version,channel,locale) references ntf_template_versions);
create table ntf_event_log(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, product_id uuid not null, event_code text not null, event_version integer not null, idempotency_key text not null, payload jsonb not null, created_at timestamptz not null default now(), foreign key(tenant_id,product_id) references ntf_tenants(id,product_id), foreign key(product_id,event_code,event_version) references ntf_events, unique(tenant_id,idempotency_key), unique(id,tenant_id));
create table ntf_notifications(id uuid primary key default gen_random_uuid(), tenant_id uuid not null, event_id uuid not null, user_id text not null, purpose text not null, title text not null, body text not null, design jsonb not null default '{}', action jsonb, created_at timestamptz not null default now(), read_at timestamptz, expires_at timestamptz, foreign key(event_id,tenant_id) references ntf_event_log(id,tenant_id), foreign key(tenant_id,user_id) references ntf_users, unique(event_id,user_id,purpose), unique(id,tenant_id));
create table ntf_deliveries(id uuid primary key default gen_random_uuid(), notification_id uuid not null, tenant_id uuid not null, channel text not null, status text not null default 'QUEUED' check(status in ('QUEUED','PROCESSING','ACCEPTED','DELIVERED','FAILED','UNKNOWN','CANCELLED')), rendered_payload jsonb not null, template_snapshot jsonb not null, provider_message_id text, attempts integer not null default 0, cost numeric(14,4), currency text, foreign key(notification_id,tenant_id) references ntf_notifications(id,tenant_id), foreign key(tenant_id,channel) references ntf_channels, unique(notification_id,channel));
create table ntf_preferences(tenant_id uuid,user_id text,channel text, enabled boolean not null, consent_at timestamptz, locale text, quiet_hours jsonb, primary key(tenant_id,user_id,channel), foreign key(tenant_id,user_id) references ntf_users, foreign key(tenant_id,channel) references ntf_channels);
create table ntf_device_tokens(id uuid primary key default gen_random_uuid(), tenant_id uuid not null,user_id text not null, token text not null, installation_id text not null, active boolean not null default true, updated_at timestamptz not null default now(), foreign key(tenant_id,user_id) references ntf_users, unique(tenant_id,installation_id));
create table ntf_jobs(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references ntf_tenants, kind text not null, payload jsonb not null, state text not null default 'READY' check(state in ('READY','LEASED','DONE','DEAD')), available_at timestamptz not null default now(), lease_until timestamptz, lease_token uuid, attempts integer not null default 0, max_attempts integer not null default 5 check(max_attempts>0), last_error text);
create table ntf_audit_logs(id bigint generated always as identity primary key, tenant_id uuid references ntf_tenants, actor text not null, action text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create index ntf_inbox_idx on ntf_notifications(tenant_id,user_id,created_at desc);
create index ntf_unread_idx on ntf_notifications(tenant_id,user_id) where read_at is null;
create index ntf_jobs_ready on ntf_jobs(available_at) where state='READY';
create index ntf_rules_event on ntf_rules(tenant_id,event_code,event_version) where active;
-- API-only boundary: no direct access by browser roles. Trusted backend must enforce scope.
revoke all on schema ntf from public, anon, authenticated;
grant usage on schema ntf to service_role;
grant all on all tables in schema ntf to service_role;
grant usage,select on all sequences in schema ntf to service_role;
do $$ declare r record; begin for r in select tablename from pg_tables where schemaname='ntf' loop execute format('alter table ntf.%I enable row level security',r.tablename); execute format('revoke all on ntf.%I from public, anon, authenticated',r.tablename); end loop; end $$;
commit;
